// Pinned "Démo" card + full-screen video player.
//
// - Card is rendered as the first item of the home live grid.
// - Same aspect-ratio and shape as LiveCard so the grid stays uniform.
// - We probe the demo video URL once on mount; if the file isn't there
//   (404/network error), the card hides itself entirely (Apple review
//   dislikes "coming soon" placeholders).
//
// Video source:
//   The demo video is served from Lovable Assets CDN. The URL is imported
//   from src/assets/demo-video.mp4.asset.json (auto-generated by the
//   lovable-assets CLI). Do not move or rename the .asset.json file.
//
// The card now uses a live-looking poster (uploaded by the team) so the home
// feed feels like a real live stream. The player opens full-screen with a
// subtle live overlay so the transition feels like entering a live room.

import { useCallback, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Play, X, Eye } from "lucide-react";
import { useTranslation } from "react-i18next";
import { Press } from "@/components/press";
import { EASE_IOS } from "@/lib/motion";
import { fetchDemoVideoUrl, DEMO_VIDEO_FALLBACK_URL } from "@/lib/demo-video-db";
import demoLivePosterAsset from "@/assets/demo-live-poster.jpg.asset.json";
import logoBadgeAsset from "@/assets/kidi-logo-badge.png.asset.json";




export const DEMO_VIDEO_URL = DEMO_VIDEO_FALLBACK_URL;

/** Resolves the current demo video URL (admin-overridable via app_config)
 *  and probes it with a HEAD request. */
export function useDemoVideo(): { ok: boolean | null; url: string } {
  const [ok, setOk] = useState<boolean | null>(null);
  const [url, setUrl] = useState<string>(DEMO_VIDEO_FALLBACK_URL);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const resolved = await fetchDemoVideoUrl().catch(() => DEMO_VIDEO_FALLBACK_URL);
      if (cancelled) return;
      setUrl(resolved);
      try {
        const r = await fetch(resolved, { method: "HEAD", cache: "no-store" });
        if (!cancelled) setOk(r.ok);
      } catch {
        if (!cancelled) setOk(false);
      }
    })();
    return () => { cancelled = true; };
  }, []);
  return { ok, url };
}

/** Back-compat: boolean-only availability probe. */
export function useDemoAvailable(): boolean | null {
  return useDemoVideo().ok;
}

