/**
 * Skeleton for the pinned demo card. Matches DemoCard's 3/4 aspect ratio and
 * rounded shape so the grid never reflows when the real card resolves. Uses
 * the same navy → gold palette (no shimmering white/gray) to stay on-brand
 * during the HEAD probe, and shows the DÉMO badge so the intent is obvious
 * even before the video is confirmed available (Apple review: no "loading…"
 * text placeholders, no ghost text).
 */
export function DemoCardSkeleton() {
  const { t } = useTranslation();
  return (
    <div
      role="status"
      aria-label={t("home.demo.title")}
      aria-busy="true"
      className="relative overflow-hidden rounded-2xl"
      style={{
        aspectRatio: "3 / 4",
        backgroundColor: "#1a1a1a",
      }}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          backgroundImage:
            "linear-gradient(to bottom, rgba(0,0,0,0.35) 0%, rgba(0,0,0,0) 35%, rgba(0,0,0,0) 60%, rgba(0,0,0,0.55) 100%)",
        }}
      />
      {/* DEMO badge */}
      <div className="absolute left-2 top-2 z-10">
        <span
          className="rounded-md px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide"
          style={{ backgroundColor: "#c8a24a", color: "#0d1530" }}
        >
          {t("home.demo.badge")}
        </span>
      </div>
      {/* LIVE badge placeholder */}
      <div className="absolute left-1/2 top-2 z-10 -translate-x-1/2">
        <div className="flex items-center gap-1.5 rounded-full bg-black/55 px-2.5 py-1">
          <span className="h-2 w-2 rounded-full bg-red-500/70" />
          <span className="text-[10px] font-bold uppercase tracking-wide text-white/70">
            LIVE
          </span>
        </div>
      </div>
      {/* subtle pulsing disk in place of the play button */}
      <div className="absolute inset-0 z-10 grid place-items-center">
        <motion.div
          animate={{ opacity: [0.35, 0.7, 0.35] }}
          transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
          className="h-16 w-16 rounded-full"
          style={{ backgroundColor: "rgba(255,255,255,0.18)" }}
        />
      </div>
    </div>
  );
}




export function DemoPlayer({
  open,
  onClose,
  src = DEMO_VIDEO_URL,
}: {
  open: boolean;
  onClose: () => void;
  src?: string;
}) {
  const { t } = useTranslation();
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    if (!open) return;
    // Restart from the beginning each time the player opens, with sound.
    const v = videoRef.current;
    if (v) {
      v.loop = true;
      v.muted = false;
      v.volume = 1;
      try { v.currentTime = 0; } catch { /* noop */ }
      const p = v.play();
      if (p) p.catch(() => { /* browser may still block sound — user can tap play */ });
    }
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  const stop = useCallback(() => {
    const v = videoRef.current;
    if (v) { v.pause(); v.currentTime = 0; }
    onClose();
  }, [onClose]);

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          key="demo-player"
          initial={{ opacity: 0, scale: 0.96 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.98 }}
          transition={{ duration: 0.25, ease: EASE_IOS }}
          className="fixed inset-0 z-[100] bg-black"
        >
          <video
            ref={videoRef}
            src={src}
            controls
            loop
            playsInline
            className="absolute inset-0 h-full w-full object-contain"
          />

          {/* live header overlay */}
          <div
            className="absolute inset-x-0 z-10 flex items-center justify-between px-3"
            style={{ top: "calc(env(safe-area-inset-top) + 12px)" }}
          >
            <div className="flex items-center gap-2">
              <div className="h-9 w-9 overflow-hidden rounded-full border border-white/30 bg-black/40">
                <img
                  src={logoBadgeAsset.url}
                  alt=""
                  className="h-full w-full object-cover"
                />

              </div>

              <div>
                <p className="text-[12px] font-semibold text-white">KIDI+ Officiel</p>
                <p className="text-[10px] text-white/70">Démo live</p>
              </div>
            </div>


            <div className="flex items-center gap-2">
              {/* LIVE badge */}
              <div className="flex items-center gap-1.5 rounded-full bg-red-600/90 px-2 py-1">
                <span className="relative flex h-2 w-2">
                  <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-white opacity-75" />
                  <span className="relative inline-flex h-2 w-2 rounded-full bg-white" />
                </span>
                <span className="text-[10px] font-bold uppercase tracking-wide text-white">
                  LIVE
                </span>
              </div>
              {/* viewers */}
              <div className="flex items-center gap-1 rounded-full bg-black/50 px-2 py-1 text-white backdrop-blur-sm">
                <Eye size={11} strokeWidth={2.2} />
                <span className="text-[10px] font-semibold">2 540</span>
              </div>
              <button
                type="button"
                onClick={stop}
                aria-label={t("home.demo.close")}
                className="grid h-11 w-11 place-items-center rounded-full bg-black/50"
              >
                <X size={22} color="white" strokeWidth={2.2} />
              </button>
            </div>
          </div>

          {/* product banner at bottom — mimics the live UI */}
          <div className="absolute inset-x-0 bottom-0 z-10 px-3 pb-3">
            <div
              className="flex items-center gap-3 rounded-2xl p-3"
              style={{ backgroundColor: "rgba(20,20,25,0.82)" }}
            >
              <div className="h-14 w-14 overflow-hidden rounded-xl bg-white/10">
                <img
                  src={demoLivePosterAsset.url}
                  alt=""
                  className="h-full w-full object-cover"
                  style={{ objectPosition: "left bottom" }}
                />
              </div>

              <div className="min-w-0 flex-1">
                <p className="truncate text-[13px] font-semibold text-white">
                  Blazer Crème Taille 38
                </p>
                <p className="mt-0.5 text-[11px] text-white/70">
                  ENCHÈRE <span className="text-[14px] font-bold text-white">45,00 €</span>
                </p>
              </div>
              <div className="flex items-center gap-1 rounded-full bg-white/15 px-2 py-1 text-white">
                <span className="text-[10px] font-semibold">00:15</span>
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

